head.script:
scwin.screenId = "jldods16010";

///////// 1. 변수 및 선언 영역 /////////

scwin.discls_minute = 4;

scwin.discls_second = 59;

scwin.discls_timer = undefined;

scwin.isBeforePW = true;

scwin.delay = false;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.checkResult();
        $("#ipt_bPw").bind("focus", function() {
                $("#text_oldid").text("");
        });
        $("#ipt_bPw").bind("focusout", function() {
                if ($(this).val().length == 0) {
                    $("#text_oldid").text("현재 비밀번호");
                }
        });
        $("#pw").bind("focus", function() {
                $("#text_newpw").text("");
        });
        $("#pw").bind("focusout", function() {
                if ($(this).val().length == 0) {
                    $("#text_newpw").text("새 비밀번호");
                }
        });
        $("#ipt_pwChk").bind("focus", function() {
                $("#text_newpw2").text("");
        });
        $("#ipt_pwChk").bind("focusout", function() {
                if ($(this).val().length == 0) {
                    $("#text_newpw2").text("새 비밀번호 확인");
                }
        });
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16010.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.delay = undefined; scwin.result = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods16010.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

