 * @returns
 * @hidden N
*/
scwin.ipt_bPw_onkeydown = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_bPw_onkeydown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if(event.ctrlKey){ await alertE("컨트롤 키를 사용할 수 없습니다."); return false;}
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16010.ipt_bPw_onkeydown' }); }
};

