/**
 * @method
 * @name scwin.startTimer2
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.startTimer2 = function () {
    /* sdd-asis-lifecycle:begin startTimer2 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.discls_timer = setInterval(async function() {
            if (scwin.discls_second == 0) {
                scwin.discls_minute = scwin.discls_minute - 1;
                scwin.discls_second = 60;
            }
            scwin.discls_second = scwin.discls_second - 1;
            if (scwin.discls_minute <= 0 && scwin.discls_second <= 0) {
                clearInterval(scwin.discls_timer);
                await alertE("휴대폰 인증번호 입력시간(5분)이 초과되었습니다.\n재시도 하십시오.");
            }
            $c.util.getComponent('txt_areaSessionTimer2').setLabel(scwin.discls_minute + ":" + ((scwin.discls_second + "").length == 1 ? '0' + scwin.discls_second : scwin.discls_second));
        }, 1000);
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
 * @method
 * @name scwin.nullChk
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.nullChk = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_NullChk — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    // ie11에서 alt값을 'undefined'로 인식하므로 수정
    if(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === ''  || typeof ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) === 'undefined') {
        return await scwin.isNull(_obj, _obj.title);
    }

    return await scwin.isNull(_obj, ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNull
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj _msg
 * @returns
 * @hidden N
*/
scwin.isNull = async function (_obj, _msg) {
    /* sdd-asis-lifecycle:begin fn_IsNull — as-is 원문 본문(전환 이관 · 포팅 적용됨) */


    if(scwin.trim(_obj.value) === ''){
        await $c.win.alert("'" + _msg + "' 항목을 입력하세요");
        _obj.focus();
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.trim
 * @author Inswave
 * @date 2026. 09. 29
 * @param _str
 * @returns
 * @hidden N
*/
scwin.trim = function (_str) {
    /* sdd-asis-lifecycle:begin fn_Trim — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

    if(typeof(_str)!=='undefined') return _str.replace(/^\s{1,}/, "").replace(/\s{1,}$/, "");
    else return _str;
    /* sdd-asis-lifecycle:end */
};


